export const NOOP_TELEMETRY: VariantsTelemetry = { track: () => undefined };

type DesignContextTelemetryEntry = {
  slot: number;
  kind: 'slug' | 'markdown';
  slug?: string;
  markdownLabel?: string;
};

export const summarizeDesignContext = (
  designContext: ReadonlyArray<DesignContextEntry | undefined> | undefined,
): DesignContextTelemetryEntry[] | null => {
  if (!designContext) return null;
  return designContext.reduce<DesignContextTelemetryEntry[]>(
    (entries, entry, slot) => {
      if (!entry) return entries;
      if (entry.kind === 'slug') {
        entries.push({ slot, kind: 'slug', slug: entry.slug });
        return entries;
      }
      entries.push({
        slot,
        kind: 'markdown',
        markdownLabel: entry.label,
      });
      return entries;
    },
    [],
  );
};

export const trackScaffoldStarted = (
  telemetry: VariantsTelemetry,
  data: {
    sessionId: string;
    variantCount: number;
    designContext?: Array<{
      slot: number;
      kind: 'slug' | 'markdown';
      slug?: string;
      markdownLabel?: string;
    }> | null;
  },
): void => {
  if (telemetry.trackAgentVariantsScaffoldStarted) {
    telemetry.trackAgentVariantsScaffoldStarted(data);
    return;
  }
  telemetry.track('agent_variants.scaffold_started', {
    source: 'mcp',
    session_id: data.sessionId,
    variant_count: data.variantCount,
    design_context: data.designContext ?? null,
  });
};

